T.update({"opt:backup_replace:label": "Varmuuskopioi ja korvaa tiedostot", "opt:backup_replace:tip": "Päällä oletuksena. Ennen kuin ajo koskee mihinkään, syöttö-regulation.bin ja msg-arkistot kopioidaan aikaleimatakansioon (backups/ ohjelman viereen), minkä jälkeen tuoreet tiedostot korvaavat ne - yksi Randomize-klikkaus siis varmuuskopioi ja asentaa.\n\nrandomized/-kansio kirjoitetaan yhä ja säilyttää raportit. Poista käytöstä, jos haluat kirjoittaa vain kansion ja jättää tiedostosi rauhaan; palauta milloin tahansa Revert-painikkeella."})
T.update({"ui:backup": "Varmuuskopioi", "ui:tip_backup": "Kopioi syöttö-regulation.bin ja msg-arkistot aikaleimattuun varmuuskop kansioon (backups/ ohjelman viereen). Ei suorita mitään.", "ui:revert": "Palauta", "ui:tip_revert": "Palauttaa viimeisimmän varmuuskopion: alkuperäinen regulation.bin ja msg-arkistot takaisin paikoilleen.", "ui:backup_none": "Ei mitään varmuuskopioitavaa", "ui:backup_none_body": "Syöttö tiedostoa ei löytynyt, joten varmuuskopioitavaa ei ole.", "ui:backup_done": "Varmuuskopiointi valmis", "ui:backup_done_body": "Alkuperäiset tiedostot kopioitu:\n{0}", "ui:revert_none": "Ei vielä varmuuskopiota", "ui:revert_none_body": "Palautettavaa varmuuskopiota ei ole. Käytä ensin Varmuuskopioi tai aja Varmuuskopioi ja korvaa -valinnalla.", "ui:revert_title": "Palataanko viimeisimpään varmuuskopioon?", "ui:revert_body": "Tämä palauttaa tiedostot kohteesta\n{0}\ntakaisin paikoilleen ja korvaa nykyiset.", "ui:revert_done": "Palautettu", "ui:revert_done_body": "{0} tiedosto(a) palautettu kohteesta:\n{1}", "ui:revert_failed": "Palautus epäonnistui", "ui:revert_failed_body": "Varmuuskopion manifestia ei voitu lukea:\n{0}"})
